CREATE   VIEW [FO].[vwIntercompany_Recon] AS

WITH BaseCount AS (
	SELECT 
	 RECID
	,COUNT(RECID) AS 'Record Count'
	FROM [synapse_fo].[LEDGERTRANS_RICS] LT
	WHERE LT.MAINACCOUNT = 000000
	GROUP BY RECID
)
,AccCount AS (
	SELECT 
	 VOUCHER
	,COUNT(DISTINCT ACCOUNTNUM) AS 'Account Count'
	,MAX(ACCOUNTNUM) AS 'Max Account No'
	FROM [synapse_fo].[CUSTTRANS_RICS] CT
	GROUP BY CT.VOUCHER
)
SELECT 
	LT.[RECID],
	LT.[GENERALJOURNALENTRY],
	LT.[ACCOUNTDISPLAYVALUE],
	LT.[JOURNALNUMBER],
	LT.[SUBLEDGERVOUCHER],
	LT.[ACCOUNTINGDATE],
	LT.[TRANSACTIONCURRENCYCODE],
	LT.[TRANSACTIONCURRENCYAMOUNT],
	LT.[ACCOUNTINGCURRENCYAMOUNT],
	LT.[REPORTINGCURRENCYAMOUNT],
	LT.[POSTINGTYPE],
	LT.[JOURNALCATEGORY],
	LT.[ISCORRECTION],
	LT.[ISCREDIT],
	LT.[ACKNOWLEDGEMENTDATE],
	LT.[DOCUMENTDATE],
	LT.[DOCUMENTNUMBER],
	LT.[MAINACCOUNT],
	LT.[TEXT],
	LT.[PAYMENTREFERENCE],
	LT.[REASONREF],
	LT.[DATAAREAID],
	LT.[RICSCOSTCENTER] AS [COSTCENTER],
	LT.[RICSCAMPAIGNYEAR] AS [CAMPAIGNYEAR],
	LT.[RICSCOUNTRY] AS [COUNTRY],
	LT.[RICSFIXEDASSETGROUP] AS [FIXEDASSETGROUP],
	LT.[RICSINTERCOMPANY] AS [INTERCOMPANY],
	LT.[RICSINTERIMREPORTINGENTITY] AS [INTERIMREPORTINGENTITY],
	LT.[RICSPRODUCTCODE] AS [PRODUCTCODE],
	LT.[RICSPRODUCTGROUP] AS [PRODUCTGROUP],
	LT.[RICSPROJECT] AS [PROJECT],
	LT.[CREATEDBY1],
	LT.[CREATEDDATETIME1]
	,CASE
		WHEN LT.DATAAREAID = 'rgre' THEN RICSINTERIMREPORTINGENTITY ELSE RICSINTERCOMPANY
		END AS 'IRE (Adj)'
	,VTR.VOUCHER AS 'Supp. Voucher'
	,VTB.ACCOUNTNUM AS 'Supp. Account No'
	,VTB.NAME AS 'Supp. Name'
	,CT.VOUCHER 'CT Voucher'
	,CTB.AccountNum AS 'Cust. Account No'
	,CTB.Name As 'Cust. Name'
	,BC.[Record Count]
	,CASE WHEN [Account Count] > 1 THEN 'Y' ELSE 'N' END AS 'Has Multiple Cust. Accounts'
FROM [synapse_fo].[LEDGERTRANS_RICS] LT
LEFT JOIN [synapse_fo].[VENDTRANS] VTR
	ON LT.SUBLEDGERVOUCHER = VTR.VOUCHER
LEFT JOIN [FO].[vwVendTable] VTB
	ON VTR.ACCOUNTNUM = VTB.ACCOUNTNUM
LEFT JOIN AccCount CT
	ON CT.VOUCHER = LT.SUBLEDGERVOUCHER
LEFT JOIN [FO].[vwCustTable] CTB
	ON CTB.AccountNum = CT.[Max Account No]
LEFT JOIN BaseCount BC
	ON BC.RECID = LT.RECID
WHERE LT.MAINACCOUNT = 000000
